// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0));
        unlockTime = bound(unlockTime, block.timestamp + 1, type(uint128).max);
        vm.deal(actor, 1 wei);
        vm.prank(actor);
        c.Put{value: 1 wei}(unlockTime);
        (uint256 storedUnlockTime, ) = c.Acc(actor);
        assertTrue(storedUnlockTime >= unlockTime);
    }
}
